() => {
  const text = document.body ? document.body.innerText : '';
  const lines = text.split(/\n+/).map(s => s.trim()).filter(Boolean);
  const interesting = lines.filter(l => /体验|开发版|0\.11\.6|选为|设为|提交审核|版本号|备注|上传/.test(l));
  return { title: document.title, lineCount: lines.length, interesting: interesting.slice(0, 80) };
}

() => {
  const text = document.body.innerText;
  const idx = text.indexOf('开发版本');
  const exp = text.indexOf('体验版');
  const snippet = (start) => start < 0 ? '' : text.slice(Math.max(0, start - 200), start + 1200);
  return {
    hasNewRemark: text.includes('供测试扫码 2026-11-20 17:12'),
    hasToday: text.includes('2026'),
    dev: snippet(idx),
    exp: snippet(exp)
  };
}

() => {
  const remark = 'dev\u73af\u5883release\uff0c\u4f9b\u6d4b\u8bd5\u626b\u7801 2026-11-20 17:12';
  const nodes = Array.from(document.querySelectorAll('body *')).filter(el => el.childNodes.length && Array.from(el.childNodes).some(n => n.nodeType === 3 && n.textContent.includes(remark)));
  const target = nodes[0];
  if (!target) return { found: false };
  let row = target;
  for (let i = 0; i < 8 && row; i++) {
    const buttons = Array.from(row.querySelectorAll('a,button,[role="button"],span')).map(el => (el.innerText || '').trim()).filter(t => t && t.length < 20);
    if (buttons.some(t => t.includes('\u4f53\u9a8c'))) {
      return { found: true, tag: row.tagName, className: row.className, buttons: buttons.slice(0, 30) };
    }
    row = row.parentElement;
  }
  const parentText = target.parentElement ? target.parentElement.innerText.slice(0, 500) : '';
  return { found: true, shallow: true, parentText };
}

() => {
  const remark = 'dev\u73af\u5883release\uff0c\u4f9b\u6d4b\u8bd5\u626b\u7801 2026-11-20 17:12';
  const other = 'update translation feature and ux';
  const all = Array.from(document.querySelectorAll('a,button,span,div'));
  const candidates = all.filter(el => (el.innerText || '').includes('\u9009\u4e3a\u4f53\u9a8c\u7248\u672c') && (el.innerText || '').includes(remark) && !(el.innerText || '').includes(other));
  candidates.sort((a,b) => a.innerText.length - b.innerText.length);
  const best = candidates[0];
  if (!best) return { found: false, candidateCount: candidates.length };
  const btn = Array.from(best.querySelectorAll('a,button,span')).find(el => (el.innerText || '').trim() === '\u9009\u4e3a\u4f53\u9a8c\u7248\u672c');
  return {
    found: true,
    candidateCount: candidates.length,
    bestLen: best.innerText.length,
    bestTag: best.tagName,
    btnTag: btn ? btn.tagName : null,
    btnClass: btn ? btn.className : null
  };
}

() => {
  const remark = 'dev\u73af\u5883release\uff0c\u4f9b\u6d4b\u8bd5\u626b\u7801 2026-11-20 17:12';
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  let node = null;
  while (walker.nextNode()) {
    if (walker.currentNode.textContent.includes(remark)) { node = walker.currentNode; break; }
  }
  if (!node) return { found: false };
  const chain = [];
  let el = node.parentElement;
  for (let i = 0; i < 10 && el; i++) {
    const direct = Array.from(el.children).map(c => (c.innerText || '').trim().replace(/\s+/g, ' ').slice(0, 40));
    chain.push({ tag: el.tagName, className: String(el.className).slice(0, 80), childCount: el.children.length, direct });
    el = el.parentElement;
  }
  return { found: true, chain };
}

