() => {
  const dialogs = Array.from(document.querySelectorAll('.weui-desktop-dialog, .dialog, [role="dialog"]')).map(el => ({
    className: String(el.className).slice(0, 100),
    display: getComputedStyle(el).display,
    text: (el.innerText || '').trim().replace(/\s+/g, ' ').slice(0, 300)
  })).filter(d => d.display !== 'none' && d.text);
  const body = document.body.innerText;
  const hasConfirm = /\u786e\u5b9a|\u786e\u8ba4|\u66ff\u6362/.test(body);
  return { dialogs, hasConfirm };
}

() => {
  const dialogs = Array.from(document.querySelectorAll('.weui-desktop-dialog'));
  const visible = dialogs.filter(el => {
    const style = getComputedStyle(el);
    const rect = el.getBoundingClientRect();
    if (style.display === 'none' || style.visibility === 'hidden' || Number(style.opacity) === 0) return false;
    let parent = el.parentElement;
    while (parent) {
      const ps = getComputedStyle(parent);
      if (ps.display === 'none' || ps.visibility === 'hidden') return false;
      parent = parent.parentElement;
    }
    return rect.width > 0 && rect.height > 0;
  }).map(el => ({
    text: (el.innerText || '').trim().replace(/\s+/g, ' ').slice(0, 220),
    buttons: Array.from(el.querySelectorAll('button,a')).map(b => (b.innerText || '').trim()).filter(Boolean).slice(0, 8)
  }));
  return { count: visible.length, visible };
}

() => {
  const dialogs = Array.from(document.querySelectorAll('.weui-desktop-dialog'));
  const dialog = dialogs.find(el => {
    const style = getComputedStyle(el);
    const rect = el.getBoundingClientRect();
    if (style.display === 'none' || style.visibility === 'hidden') return false;
    let parent = el.parentElement;
    while (parent) {
      const ps = getComputedStyle(parent);
      if (ps.display === 'none' || ps.visibility === 'hidden') return false;
      parent = parent.parentElement;
    }
    return rect.width > 0 && rect.height > 0 && (el.innerText || '').includes('\u5207\u6362\u4f53\u9a8c\u7248');
  });
  if (!dialog) return { ok: false, reason: 'dialog' };
  const btn = Array.from(dialog.querySelectorAll('button')).find(b => (b.innerText || '').trim() === '\u5207\u6362\u4f53\u9a8c\u7248');
  if (!btn) return { ok: false, reason: 'button' };
  btn.click();
  return { ok: true };
}

